const input=$json;
const trigger=String(input.trigger_type ?? '');
const campaign=input.campaign ?? {};

function stable(value){
  if(value===null || typeof value!=='object') return JSON.stringify(value);
  if(Array.isArray(value)) return '['+value.map(stable).join(',')+']';
  return '{'+Object.keys(value).sort().map((key)=>JSON.stringify(key)+':'+stable(value[key])).join(',')+'}';
}
function fingerprint(value){
  const text=stable(value);
  let hash=2166136261;
  for(let i=0;i<text.length;i++){
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash,16777619);
  }
  return 'fnv1a32:'+((hash>>>0).toString(16).padStart(8,'0'));
}
function campaignSnapshot(c){
  return {
    campaign_id:c.id ?? null,
    name:c.name ?? null,
    segment_rules:c.segment_rules ?? {},
    offer_rules:c.offer_rules ?? {},
    starts_at:c.starts_at ?? null,
    ends_at:c.ends_at ?? null
  };
}
function policyExclusion(policy){
  if(policy?.opt_out===true) return 'OPT_OUT';
  if(policy?.suppressed===true) return 'SUPPRESSED';
  if(policy?.human_lock===true) return 'HUMAN_LOCK';
  if(policy?.contactable===false) return 'NOT_CONTACTABLE';
  return null;
}

const snap=campaignSnapshot(campaign);
const currentHash=fingerprint(snap);

if(!campaign.id){
  return {json:{
    guard_required:false,
    lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_ID_REQUIRED']}
  }};
}

if(trigger==='build_snapshot'){
  if(campaign.status!=='draft'){
    return {json:{
      guard_required:false,
      lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_SNAPSHOT_REQUIRES_DRAFT']}
    }};
  }
  const candidates=Array.isArray(input.candidate_events)?input.candidate_events:[];
  const operations=[{
    action:'UPDATE_CAMPAIGN_SNAPSHOT_METADATA',
    campaign_id:campaign.id,
    current_snapshot_hash:currentHash,
    member_count:candidates.length,
    generated_at:input.now ?? 'NOW'
  }];
  let eligibleCount=0;
  let excludedCount=0;

  for(const candidate of candidates){
    const eventId=candidate.customer_event_id ?? null;
    if(!eventId) continue;
    let reason=null;
    if(candidate.segment_match!==true) reason='SEGMENT_QUERY_NOT_MATCHED';
    if(!reason) reason=policyExclusion(candidate.current_policy ?? {});
    const eligibilityStatus=reason?'excluded':'eligible';
    if(reason) excludedCount+=1; else eligibleCount+=1;

    operations.push({
      action:'UPSERT_CAMPAIGN_MEMBER',
      idempotency_key:'campaign-member:'+campaign.id+':'+eventId,
      campaign_id:campaign.id,
      customer_event_id:eventId,
      eligibility_status:eligibilityStatus,
      eligibility_reason:reason ?? 'SEGMENT_MATCH',
      segment_snapshot:{
        campaign_snapshot_hash:currentHash,
        segment_rules:campaign.segment_rules ?? {},
        query_match:candidate.segment_match===true,
        commercial_stage:candidate.commercial_stage ?? null,
        event_status:candidate.status ?? null,
        evaluated_policy:{
          opt_out:Boolean(candidate.current_policy?.opt_out),
          suppressed:Boolean(candidate.current_policy?.suppressed),
          human_lock:Boolean(candidate.current_policy?.human_lock),
          contactable:candidate.current_policy?.contactable!==false
        }
      },
      offer_snapshot:campaign.offer_rules ?? {}
    });
  }

  operations.push({
    action:'CREATE_HUMAN_TASK',
    task_type:'campaign_approval',
    reason_code:'CAMPAIGN_SNAPSHOT_READY',
    payload:{
      campaign_id:campaign.id,
      snapshot_hash:currentHash,
      eligible_count:eligibleCount,
      excluded_count:excludedCount
    }
  });
  operations.push({
    action:'EMIT_EVENT',
    event_type:'campaign_snapshot_created',
    campaign_id:campaign.id,
    snapshot_hash:currentHash
  });

  return {json:{
    guard_required:false,
    lifecycle_plan:{
      status:'snapshot_ready',
      snapshot_hash:currentHash,
      eligible_count:eligibleCount,
      excluded_count:excludedCount,
      operations,
      blockers:[]
    }
  }};
}

if(trigger==='human_approve'){
  const actor=String(input.actor_type ?? '').toLowerCase();
  const actorRef=input.actor_ref ?? null;
  const reviewHash=input.review_snapshot_hash ?? null;
  const eligibleCount=Number(input.eligible_member_count ?? 0);

  if(actor!=='human' || !actorRef){
    return {json:{
      guard_required:false,
      lifecycle_plan:{status:'denied',operations:[],blockers:['CAMPAIGN_APPROVAL_REQUIRES_IDENTIFIED_HUMAN']}
    }};
  }
  if(campaign.status!=='draft'){
    return {json:{
      guard_required:false,
      lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_APPROVAL_REQUIRES_DRAFT']}
    }};
  }
  if(!reviewHash || reviewHash!==currentHash){
    return {json:{
      guard_required:false,
      lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_SNAPSHOT_CHANGED_REAPPROVAL_REQUIRED']}
    }};
  }
  if(eligibleCount<=0){
    return {json:{
      guard_required:false,
      lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_NO_ELIGIBLE_MEMBERS']}
    }};
  }

  return {json:{
    guard_required:false,
    lifecycle_plan:{
      status:'approved',
      approval_snapshot_hash:currentHash,
      operations:[
        {
          action:'UPDATE_CAMPAIGN_STATUS',
          campaign_id:campaign.id,
          from_status:'draft',
          to_status:'approved',
          approved_by:actorRef,
          metadata_patch:{
            approval_snapshot_hash:currentHash,
            approved_at:input.now ?? 'NOW',
            approved_member_count:eligibleCount
          }
        },
        {
          action:'APPROVE_ELIGIBLE_CAMPAIGN_MEMBERS',
          campaign_id:campaign.id,
          expected_snapshot_hash:currentHash,
          from_status:'eligible',
          to_status:'approved'
        },
        {
          action:'EMIT_EVENT',
          event_type:'campaign_approved',
          campaign_id:campaign.id,
          snapshot_hash:currentHash,
          approved_by:actorRef
        }
      ],
      blockers:[]
    }
  }};
}

if(trigger==='dispatch_candidate'){
  const member=input.member ?? {};
  const approvalHash=campaign.metadata?.approval_snapshot_hash ?? campaign.approval_snapshot_hash ?? null;
  return {json:{
    guard_required:true,
    lifecycle_plan:{
      status:'guard_pending',
      campaign_id:campaign.id,
      customer_event_id:member.customer_event_id ?? null,
      member_id:member.id ?? null,
      snapshot_hash:currentHash,
      blockers:[]
    },
    campaign:{
      id:campaign.id,
      status:campaign.status,
      approved_by:campaign.approved_by ?? null,
      starts_at:campaign.starts_at ?? null,
      ends_at:campaign.ends_at ?? null,
      approval_snapshot_hash:approvalHash
    },
    current_snapshot_hash:currentHash,
    member,
    current_policy:input.current_policy ?? {},
    now:input.now ?? null,
    whatsapp_window_open:Boolean(input.whatsapp_window_open),
    template_approved:Boolean(input.template_approved),
    approved_template_name:input.approved_template_name ?? null,
    candidate_text:input.candidate_text ?? '',
    claimed_prices:input.claimed_prices ?? null,
    quote_result:input.quote_result ?? null,
    availability_claim:input.availability_claim ?? 'none',
    reservation_confirmed:Boolean(input.reservation_confirmed),
    asked_fact_keys:input.asked_fact_keys ?? [],
    current_facts:input.current_facts ?? {},
    contains_pii:Boolean(input.contains_pii),
    contains_secret:Boolean(input.contains_secret),
    allowed_links:input.allowed_links ?? []
  }};
}

if(trigger==='dispatch_success'){
  const member=input.member ?? {};
  if(!input.external_message_id){
    return {json:{guard_required:false,lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_EXTERNAL_MESSAGE_ID_REQUIRED']}}};
  }
  if(['sent','responded','converted'].includes(String(member.eligibility_status ?? ''))){
    return {json:{guard_required:false,lifecycle_plan:{status:'duplicate_noop',operations:[],blockers:[]}}};
  }
  if(member.eligibility_status!=='approved'){
    return {json:{guard_required:false,lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_MEMBER_NOT_APPROVED']}}};
  }
  const approvalHash=campaign.metadata?.approval_snapshot_hash ?? null;
  if(!approvalHash || approvalHash!==currentHash){
    return {json:{guard_required:false,lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_SNAPSHOT_CHANGED_REAPPROVAL_REQUIRED']}}};
  }
  return {json:{
    guard_required:false,
    lifecycle_plan:{
      status:'sent',
      operations:[
        {
          action:'UPDATE_CAMPAIGN_MEMBER_STATUS',
          member_id:member.id ?? null,
          campaign_id:campaign.id,
          customer_event_id:member.customer_event_id ?? null,
          from_status:'approved',
          to_status:'sent',
          external_message_id:input.external_message_id
        },
        {
          action:'EMIT_EVENT',
          event_type:'campaign_sent',
          campaign_id:campaign.id,
          customer_event_id:member.customer_event_id ?? null,
          external_message_id:input.external_message_id,
          idempotency_key:'campaign-sent:'+campaign.id+':'+String(member.customer_event_id ?? '')+':'+input.external_message_id
        }
      ],
      blockers:[]
    }
  }};
}

if(trigger==='customer_response'){
  const member=input.member ?? {};
  if(member.eligibility_status==='responded' || member.eligibility_status==='converted'){
    return {json:{guard_required:false,lifecycle_plan:{status:'duplicate_noop',operations:[],blockers:[]}}};
  }
  if(member.eligibility_status!=='sent'){
    return {json:{guard_required:false,lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_RESPONSE_REQUIRES_SENT_MEMBER']}}};
  }
  return {json:{
    guard_required:false,
    lifecycle_plan:{
      status:'responded',
      operations:[
        {action:'UPDATE_CAMPAIGN_MEMBER_STATUS',member_id:member.id ?? null,from_status:'sent',to_status:'responded'},
        {action:'EMIT_EVENT',event_type:'campaign_responded',campaign_id:campaign.id,customer_event_id:member.customer_event_id ?? null}
      ],
      blockers:[]
    }
  }};
}

if(trigger==='converted'){
  const member=input.member ?? {};
  if(member.eligibility_status==='converted'){
    return {json:{guard_required:false,lifecycle_plan:{status:'duplicate_noop',operations:[],blockers:[]}}};
  }
  if(!['sent','responded'].includes(String(member.eligibility_status ?? ''))){
    return {json:{guard_required:false,lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_CONVERSION_REQUIRES_SENT_OR_RESPONDED']}}};
  }
  return {json:{
    guard_required:false,
    lifecycle_plan:{
      status:'converted',
      operations:[
        {action:'UPDATE_CAMPAIGN_MEMBER_STATUS',member_id:member.id ?? null,to_status:'converted'},
        {action:'EMIT_EVENT',event_type:'campaign_converted',campaign_id:campaign.id,customer_event_id:member.customer_event_id ?? null}
      ],
      blockers:[]
    }
  }};
}

return {json:{
  guard_required:false,
  lifecycle_plan:{status:'blocked',operations:[],blockers:['CAMPAIGN_TRIGGER_UNKNOWN']}
}};

